const std = @import("std");

fn partition(arr: []i32, low: usize, high: usize) usize {
    const pivot = arr[high];
    var i: usize = low;
    var j: usize = low;
    while (j < high) {
        if (arr[j] <= pivot) {
            const temp = arr[i]; arr[i] = arr[j]; arr[j] = temp;
            i += 1;
        }
        j += 1;
    }
    const temp = arr[i]; arr[i] = arr[high]; arr[high] = temp;
    return i;
}

fn quickSelect(arr: []i32, low: usize, high: usize, k: usize) i32 {
    if (low == high) return arr[low];
    const pi = partition(arr, low, high);
    if (k == pi) return arr[pi];
    return if (k < pi) quickSelect(arr, low, pi -| 1, k) else quickSelect(arr, pi + 1, high, k);
}

pub fn main() !void {
    var arr = [_]i32{ 7, 10, 4, 3, 20, 15 };
    const k: usize = 3;
    const result = quickSelect(arr, 0, arr.len - 1, k - 1);
    std.debug.print("The {}rd smallest is {}\n", .{k, result});
}
